using HRIS.Api.DTOs.Parking; using HRIS.Api.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace HRIS.Api.Controllers; [ApiController][Route("api/parking")][Authorize] public class ParkingController:ControllerBase { private readonly IParkingService _service; public ParkingController(IParkingService service)=>_service=service; [HttpGet("vehicle-types")] public async Task<IActionResult> VehicleTypes()=>Ok(await _service.GetVehicleTypesAsync()); [HttpGet] public async Task<IActionResult> Get()=>Ok(await _service.GetAsync(User.ToUserContext())); [HttpPost] public async Task<IActionResult> Create(ParkingCreateDto dto)=>Ok(await _service.CreateAsync(dto,User.ToUserContext())); [HttpPost("{id:int}/status")][Authorize(Roles="HR,Support")] public async Task<IActionResult> Status(int id,[FromQuery]string status){await _service.UpdateStatusAsync(id,status,User.ToUserContext());return NoContent();} }
